INSERT INTO arelore_education.user_detection_type
(type_code, type_name, type_description, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', '软考-系统架构设计师-2017年下半年-综合知识', '全国计算机技术与软件专业技术资格（水平）考试 系统架构设计师 2017年下半年 综合知识试题与解析', '{"source":"2017年下半年 系统架构设计师 答案详解.docx","exam":"系统架构设计师","year":"2017","term":"下半年","session":"综合知识","questionCount":68,"scoring":{"resultMode":"objective_sum","scoreDimension":"score","maxScore":68,"scoringVersion":"1.0"},"resultMeanings":{}}')
ON DUPLICATE KEY UPDATE
                     type_name = VALUES(type_name),
                     type_description = VALUES(type_description),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q001', '某计算机系统采用5级流水线结构执行指令，设每条指令的执行由取指令(2∆t)、分析指令(1∆t)、取操作数(3∆t)、运算(1∆t)和写回结果(2∆t)组成，并分别用5个子部完成，该流水线的最大吞吐率为(1);若连续向流水线输入10条指令，则该流水线的加速比为(2).', 1, '单选题', '[{"key":"A","text":"1/9∆t","scores":{"score":0}},{"key":"B","text":"1/3∆t","scores":{"score":1}},{"key":"C","text":"1/2∆t","scores":{"score":0}},{"key":"D","text":"1/1∆t","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":1,"correctOptionKey":"B","explanation":"本题考查流水线计算。\\n(1)流水线周期为：3t。\\n流水线的吞吐率为：指令条数/流水线执行时间。\\n即：\\nn/(2t+1t+3t+1t+2t+(n-1)*3t)=n/(6t+3nt)\\n流水线的最大吞吐率就是上面的式子中，n趋向于无穷大的结果。当n趋向于无穷大时，上式的结果为：1/3t。所以应该选B。\\n(2)流水线加速比=不用流水线的执行时间/使用流水线的执行时间\\n10条指令不用流水线的执行时间=（2t+1t+3t+1t+2t）*10=90t。\\n10条指令使用流水线的执行时间=（2t+1t+3t+1t+2t）+（10-1）*3t=36t。\\n所以加速比为：90t/36t=5:2","imageHashValues":[],"fullExplanation":"本题考查流水线计算。\\n(1)流水线周期为：3t。\\n流水线的吞吐率为：指令条数/流水线执行时间。\\n即：\\nn/(2t+1t+3t+1t+2t+(n-1)*3t)=n/(6t+3nt)\\n流水线的最大吞吐率就是上面的式子中，n趋向于无穷大的结果。当n趋向于无穷大时，上式的结果为：1/3t。所以应该选B。\\n(2)流水线加速比=不用流水线的执行时间/使用流水线的执行时间\\n10条指令不用流水线的执行时间=（2t+1t+3t+1t+2t）*10=90t。\\n10条指令使用流水线的执行时间=（2t+1t+3t+1t+2t）+（10-1）*3t=36t。\\n所以加速比为：90t/36t=5:2"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q002', '某计算机系统采用5级流水线结构执行指令，设每条指令的执行由取指令(2∆t)、分析指令(1∆t)、取操作数(3∆t)、运算(1∆t)和写回结果(2∆t)组成，并分别用5个子部完成，该流水线的最大吞吐率为(1);若连续向流水线输入10条指令，则该流水线的加速比为(2).', 2, '单选题', '[{"key":"A","text":"1:10","scores":{"score":0}},{"key":"B","text":"2:1","scores":{"score":0}},{"key":"C","text":"5:2","scores":{"score":1}},{"key":"D","text":"3:1","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":2,"correctOptionKey":"C","explanation":"本题考查流水线计算。\\n(1)流水线周期为：3t。\\n流水线的吞吐率为：指令条数/流水线执行时间。\\n即：\\nn/(2t+1t+3t+1t+2t+(n-1)*3t)=n/(6t+3nt)\\n流水线的最大吞吐率就是上面的式子中，n趋向于无穷大的结果。当n趋向于无穷大时，上式的结果为：1/3t。所以应该选B。\\n(2)流水线加速比=不用流水线的执行时间/使用流水线的执行时间\\n10条指令不用流水线的执行时间=（2t+1t+3t+1t+2t）*10=90t。\\n10条指令使用流水线的执行时间=（2t+1t+3t+1t+2t）+（10-1）*3t=36t。\\n所以加速比为：90t/36t=5:2","imageHashValues":[],"fullExplanation":"本题考查流水线计算。\\n(1)流水线周期为：3t。\\n流水线的吞吐率为：指令条数/流水线执行时间。\\n即：\\nn/(2t+1t+3t+1t+2t+(n-1)*3t)=n/(6t+3nt)\\n流水线的最大吞吐率就是上面的式子中，n趋向于无穷大的结果。当n趋向于无穷大时，上式的结果为：1/3t。所以应该选B。\\n(2)流水线加速比=不用流水线的执行时间/使用流水线的执行时间\\n10条指令不用流水线的执行时间=（2t+1t+3t+1t+2t）*10=90t。\\n10条指令使用流水线的执行时间=（2t+1t+3t+1t+2t）+（10-1）*3t=36t。\\n所以加速比为：90t/36t=5:2"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q003', 'DMA (直接存储器访问)工作方式是在（3）之间建立起直接的数据通路。', 3, '单选题', '[{"key":"A","text":"CPU 与外设","scores":{"score":0}},{"key":"B","text":"CPU 与主存","scores":{"score":0}},{"key":"C","text":"主存与外设 D .外设与外设","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":3,"correctOptionKey":"C","explanation":"直接主存存取（Direct Memory Access，DMA）是指数据在主存与I/O设备间的直接成块传送，即在主存与I/O设备间传送数据块的过程中，不需要CPU作任何干涉，只需在过程开始启动（即向设备发出“传送一块数据”的命令）与过程结束（CPU通过轮询或中断得知过程是否结束和下次操作是否准备就绪）时由CPU进行处理，实际操作由DMA硬件直接完成，CPU在传送过程中可做其它事情。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

