VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q013', '下面可提供安全电子邮件服务的是（13）。', 13, '单选题', '[{"key":"A","text":"RSA","scores":{"score":0}},{"key":"B","text":"SSL","scores":{"score":0}},{"key":"C","text":"SET","scores":{"score":0}},{"key":"D","text":"S/MIME","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":13,"correctOptionKey":"D","explanation":"MIME(Multipurpose Internet Mail Extensions)中文名为：多用途互联网邮件扩展类型。Internet电子邮件由一个邮件头部和一个可选的邮件主体组成，其中邮件头部含有邮件的发送方和接收方的有关信息。而MIME是针对邮件主体的一种扩展描述机制。它设定某种扩展名的文件用一种应用程序来打开的方式类型，当该扩展名文件被访问的时候，浏览器会自动使用指定应用程序来打开。多用于指定一些客户端自定义的文件名，以及一些媒体文件打开方式。所以这是与邮件内容直接相关的一个协议。\\n而S/MIME (Secure Multipurpose Internet Mail Extensions)是对MIME在安全方面的扩展。它可以把MIME实体(比如数字签名和加密信息等)封装成安全对象。增强安全服务，例如具有接收方确认签收的功能，这样就可以确保接收者不能否认已经收到过的邮件。还可以用于提供数据保密、完整性保护、认证和鉴定服务等功能。\\nS/MIME只保护邮件的邮件主体，对头部信息则不进行加密，以便让邮件成功地在发送者和接收者的网关之间传递。","imageHashValues":[],"fullExplanation":"MIME(Multipurpose Internet Mail Extensions)中文名为：多用途互联网邮件扩展类型。Internet电子邮件由一个邮件头部和一个可选的邮件主体组成，其中邮件头部含有邮件的发送方和接收方的有关信息。而MIME是针对邮件主体的一种扩展描述机制。它设定某种扩展名的文件用一种应用程序来打开的方式类型，当该扩展名文件被访问的时候，浏览器会自动使用指定应用程序来打开。多用于指定一些客户端自定义的文件名，以及一些媒体文件打开方式。所以这是与邮件内容直接相关的一个协议。\\n而S/MIME (Secure Multipurpose Internet Mail Extensions)是对MIME在安全方面的扩展。它可以把MIME实体(比如数字签名和加密信息等)封装成安全对象。增强安全服务，例如具有接收方确认签收的功能，这样就可以确保接收者不能否认已经收到过的邮件。还可以用于提供数据保密、完整性保护、认证和鉴定服务等功能。\\nS/MIME只保护邮件的邮件主体，对头部信息则不进行加密，以便让邮件成功地在发送者和接收者的网关之间传递。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

