    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q014', '网络逻辑结构设计的内容不包括（14）。', 14, '单选题', '[{"key":"A","text":"逻辑网络设计图","scores":{"score":0}},{"key":"B","text":"IP地址方案","scores":{"score":0}},{"key":"C","text":"具体的软硬件、广域网连接和基本服务","scores":{"score":0}},{"key":"D","text":"用户培训计划","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":14,"correctOptionKey":"D","explanation":"利用需求分析和现有网络体系分析的结果来设计逻辑网络结构，最后得到一份逻辑网络设计文档，输出内容包括以下几点：\\n1、逻辑网络设计图\\n2、IP地址方案\\n3、安全方案\\n4、招聘和培训网络员工的具体说明\\n5、对软硬件、服务、员工和培训的费用初步估计\\n物理网络设计是对逻辑网络设计的物理实现，通过对设备的具体物理分布、运行环境等确定，确保网络的物理连接符合逻辑连接的要求。输出如下内容：\\n1、网络物理结构图和布线方案\\n2、设备和部件的详细列表清单\\n3、软硬件和安装费用的估算\\n4、安装日程表，详细说明服务的时间以及期限\\n5、安装后的测试计划\\n6、用户的培训计划\\n由此可以看出D选项的工作是物理网络设计阶段的任务。","imageHashValues":[],"fullExplanation":"利用需求分析和现有网络体系分析的结果来设计逻辑网络结构，最后得到一份逻辑网络设计文档，输出内容包括以下几点：\\n1、逻辑网络设计图\\n2、IP地址方案\\n3、安全方案\\n4、招聘和培训网络员工的具体说明\\n5、对软硬件、服务、员工和培训的费用初步估计\\n物理网络设计是对逻辑网络设计的物理实现，通过对设备的具体物理分布、运行环境等确定，确保网络的物理连接符合逻辑连接的要求。输出如下内容：\\n1、网络物理结构图和布线方案\\n2、设备和部件的详细列表清单\\n3、软硬件和安装费用的估算\\n4、安装日程表，详细说明服务的时间以及期限\\n5、安装后的测试计划\\n6、用户的培训计划\\n由此可以看出D选项的工作是物理网络设计阶段的任务。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

