                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q022', '项目范围管理中，范围定义的输入包括（22）。', 22, '单选题', '[{"key":"A","text":"项目章程、项目范围管理计划、产品范围说明书和变更申请","scores":{"score":0}},{"key":"B","text":"项目范围描述、产品范围说明书、生产项目计划和组织过程资产","scores":{"score":0}},{"key":"C","text":"项目章程、项目范围管理计划、组织过程资产和批准的变更申请","scores":{"score":1}},{"key":"D","text":"生产项目计划、项目可交付物说明、信息系统要求说明和项目质量标准","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":22,"correctOptionKey":"C","explanation":"在初步项目范围说明书中已文档化的主要的可交付物、假设和约束条件的基础上准备详细的项目范围说明书，是项目成功的关键。范围定义的输入包括以下内容：\\n① 项目章程。如果项目章程或初始的范围说明书没有在项目执行组织中使用，同样的信息需要进一步收集和开发，以产生详细的项目范围说明书。\\n② 项目范围管理计划。\\n③ 组织过程资产。\\n④ 批准的变更申请。\\n\\n项目配置管理中，产品配置是指一个产品在其生命周期各个阶段所产生的各种形式和各种版本的文档、计算机程序、部件及数据的集合。该集合中的每一个元素称为 该产品配置中的一个配置顶，（23）不属于产品组成部分工作成果的配置顶。\\n (23)A.需求文档B.设计文档C.工作计划D.源代码\\n【答案】C\\n【解析】\\n配置项是构成产品配置的主要元素，配置项主要有以下两大类：\\n（1）属于产品组成部分的工作成果：如需求文档、设计文档、源代码和测试用例等；\\n（2）属于项目管理和机构支撑过程域产生的文档：如工作计划、项目质量报告和项目跟踪报告等。\\n这些文档虽然不是产品的组成部分，但是值得保存。所以设备清单不属于配置项。所以选项C的工作计划虽可充当配置项，但不属于产品组成部分工作成果的配置项。","imageHashValues":[],"fullExplanation":"在初步项目范围说明书中已文档化的主要的可交付物、假设和约束条件的基础上准备详细的项目范围说明书，是项目成功的关键。范围定义的输入包括以下内容：\\n① 项目章程。如果项目章程或初始的范围说明书没有在项目执行组织中使用，同样的信息需要进一步收集和开发，以产生详细的项目范围说明书。\\n② 项目范围管理计划。\\n③ 组织过程资产。\\n④ 批准的变更申请。\\n\\n项目配置管理中，产品配置是指一个产品在其生命周期各个阶段所产生的各种形式和各种版本的文档、计算机程序、部件及数据的集合。该集合中的每一个元素称为 该产品配置中的一个配置顶，（23）不属于产品组成部分工作成果的配置顶。\\n (23)A.需求文档B.设计文档C.工作计划D.源代码\\n【答案】C\\n【解析】\\n配置项是构成产品配置的主要元素，配置项主要有以下两大类：\\n（1）属于产品组成部分的工作成果：如需求文档、设计文档、源代码和测试用例等；\\n（2）属于项目管理和机构支撑过程域产生的文档：如工作计划、项目质量报告和项目跟踪报告等。\\n这些文档虽然不是产品的组成部分，但是值得保存。所以设备清单不属于配置项。所以选项C的工作计划虽可充当配置项，但不属于产品组成部分工作成果的配置项。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
