VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q024', '以下关于需求陈述的描述中,（24）是不正确的。', 24, '单选题', '[{"key":"A","text":"每一项需求都必须完整、准确地描述即将要开发的功能","scores":{"score":0}},{"key":"B","text":"需求必须能够在系统及其运行环境的能力和约束条件内实现","scores":{"score":0}},{"key":"C","text":"每一项需求记录的功能都必须是用户的真正的需要","scores":{"score":0}},{"key":"D","text":"在良好的需求陈述中，所有需求都应被视为同等重要","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":24,"correctOptionKey":"D","explanation":"一个好的变更控制过程，给项目风险承担者提供了正式的建议变更机制。如下图所示的需求变更管理过程中，①②③处对应的内容应分别是(25)。\\n 【img:275cd18088c0b89fb0f28a41d794ece587abf8afe37bcd3a2eca1dd89c506152】","imageHashValues":["275cd18088c0b89fb0f28a41d794ece587abf8afe37bcd3a2eca1dd89c506152"],"fullExplanation":"一个好的变更控制过程，给项目风险承担者提供了正式的建议变更机制。如下图所示的需求变更管理过程中，①②③处对应的内容应分别是(25)。\\n 【img:275cd18088c0b89fb0f28a41d794ece587abf8afe37bcd3a2eca1dd89c506152】"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
