INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q025', '第25题', 25, '单选题', '[{"key":"A","text":"问题分析与变更描述、变更分析与成本计算、变更实现","scores":{"score":1}},{"key":"B","text":"变更描述与成本计算、变更分析、变更实现","scores":{"score":0}},{"key":"C","text":"问题分析与变更分析、成本计算、变更实现","scores":{"score":0}},{"key":"D","text":"变更描述、变更分析与变更实现、成本计算","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":25,"correctOptionKey":"A","explanation":"在需求管理过程中需求的变更是受严格管控的，其流程为：\\n1、问题分析和变更描述。这是识别和分析需求问题或者一份明确的变更提议，以检查它的有效性，从而产生一个更明确的需求变更提议。\\n2、变更分析和成本计算。使用可追溯性信息和系统需求的一般知识，对需求变更提议进行影响分析和评估。变更成本计算应该包括对需求文档的修改、系统修改的设计和实现的成本。一旦分析完成并且确认，应该进行是否执行这一变更的决策。\\n3、变更实现。这要求需求文档和系统设计以及实现都要同时修改。如果先对系统的程序做变更，然后再修改需求文档，这几乎不可避免地会出现需求文档和程序的不一致。","imageHashValues":[],"fullExplanation":"在需求管理过程中需求的变更是受严格管控的，其流程为：\\n1、问题分析和变更描述。这是识别和分析需求问题或者一份明确的变更提议，以检查它的有效性，从而产生一个更明确的需求变更提议。\\n2、变更分析和成本计算。使用可追溯性信息和系统需求的一般知识，对需求变更提议进行影响分析和评估。变更成本计算应该包括对需求文档的修改、系统修改的设计和实现的成本。一旦分析完成并且确认，应该进行是否执行这一变更的决策。\\n3、变更实现。这要求需求文档和系统设计以及实现都要同时修改。如果先对系统的程序做变更，然后再修改需求文档，这几乎不可避免地会出现需求文档和程序的不一致。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q026', '软件过程是制作软件产品的一组活动以及结果，这些活动主要由软件人员来完成，主要包括（26）。软件过程模型是软件开发实际过程的抽象与概括，它应该包括构成软件过程的各种活动。软件过程有各种各样的模型，其中，（27）的活动之间存在因果关系，前一阶段工作的结果是后一段阶段工作的输入描述。', 26, '单选题', '[{"key":"A","text":"软件描述、软件开发和软件测试","scores":{"score":0}},{"key":"B","text":"软件开发、软件有效性验证和软件测试","scores":{"score":0}},{"key":"C","text":"软件描述、软件设计、软件实现和软件测试","scores":{"score":0}},{"key":"D","text":"软件描述、软件开发、软件有效性验证和软件进化","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":26,"correctOptionKey":"D","explanation":"软件过程模型的基本概念：软件过程是制作软件产品的一组活动以及结果，这些活动主要由软件人员来完成，软件活动主要有：\\n(1) 软件描述。必须定义软件功能以及使用的限制。\\n(2) 软件开发。也就是软件的设计和实现，软件工程人员制作出能满足描述的软件。\\n(3) 软件有效性验证。软件必须经过严格的验证，以保证能够满足客户的需求。\\n(4) 软件进化。软件随着客户需求的变化不断地改进。\\n瀑布模型的特点是因果关系紧密相连，前一个阶段工作的结果是后一个阶段工作的输入。或者说，每一个阶段都是建筑在前一个阶段正确结果之上，前一个阶段的错漏会隐蔽地带到后一个阶段。这种错误有时甚至可能是灾难性的。因此每一个阶段工作完成后，都要进行审查和确认，这是非常重要的。历史上，瀑布模型起到了重要作用，它的出现有利于人员的组织管理，有利于软件开发方法和工具的研究。","imageHashValues":[],"fullExplanation":"软件过程模型的基本概念：软件过程是制作软件产品的一组活动以及结果，这些活动主要由软件人员来完成，软件活动主要有：\\n(1) 软件描述。必须定义软件功能以及使用的限制。\\n(2) 软件开发。也就是软件的设计和实现，软件工程人员制作出能满足描述的软件。\\n(3) 软件有效性验证。软件必须经过严格的验证，以保证能够满足客户的需求。\\n(4) 软件进化。软件随着客户需求的变化不断地改进。\\n瀑布模型的特点是因果关系紧密相连，前一个阶段工作的结果是后一个阶段工作的输入。或者说，每一个阶段都是建筑在前一个阶段正确结果之上，前一个阶段的错漏会隐蔽地带到后一个阶段。这种错误有时甚至可能是灾难性的。因此每一个阶段工作完成后，都要进行审查和确认，这是非常重要的。历史上，瀑布模型起到了重要作用，它的出现有利于人员的组织管理，有利于软件开发方法和工具的研究。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

