VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q030', 'UNIX的源代码控制工具（Source Code control System，SCCS）是软件项目开发中常用的（30）。', 30, '单选题', '[{"key":"A","text":"源代码静态分析工具","scores":{"score":0}},{"key":"B","text":"文档分析工具","scores":{"score":0}},{"key":"C","text":"版本控制工具","scores":{"score":1}},{"key":"D","text":"再工程工具","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":30,"correctOptionKey":"C","explanation":"版本控制软件提供完备的版本管理功能，用于存储、追踪目录（文件夹）和文件的修改历史，是软件开发者的必备工具，是软件公司的基础设施。版本控制软件的最高目标，是支持软件公司的配置管理活动，追踪多个版本的开发和维护活动，及时发布软件。SCCS是元老级的版本控制软件，也叫配置管理软件。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
