    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q031', '结构化程序设计采用自顶向下、逐步求精及模块化的程序设计方法，通过（31）三种基本的控制结构可以构造出任何单入口单出口的程序。', 31, '单选题', '[{"key":"A","text":"顺序、选择和嵌套","scores":{"score":0}},{"key":"B","text":"顺序、分支和循环","scores":{"score":1}},{"key":"C","text":"分支、并发和循环","scores":{"score":0}},{"key":"D","text":"跳转、选择和并发","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":31,"correctOptionKey":"B","explanation":"","imageHashValues":[]}')
