INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q035', '软件构件是一个独立可部署的软件单元，与程序设计中的对象不同，构件（35）。', 35, '单选题', '[{"key":"A","text":"是一个实例单元，具有唯一的标志","scores":{"score":0}},{"key":"B","text":"可以利用容器管理自身对外的可见状态","scores":{"score":0}},{"key":"C","text":"利用工厂方法(如构造函数）来创建自己的实例","scores":{"score":1}},{"key":"D","text":"之间可以共享一个类元素","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":35,"correctOptionKey":"C","explanation":"本题考查构件与对象的概念\\n构件的特性是:\\n（1）独立部署单元； \\n（2）作为第三方的组装单元； \\n（3）没有（外部的）可见状态。 \\n一个构件可以包含多个类元素，但是一个类元素只能属于一个构件。将一个类拆分进行部署通常没什么意义。\\n对象的特性是：\\n（1）一个实例单元，具有唯一的标志。\\n（2）可能具有状态，此状态外部可见。\\n（3）封装了自己的状态和行为。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q036', '为了使一个接口的规范和实现该接口的构件得到广泛应用，需要实现接口的标准化。接口标准化是对（36）的标准化。', 36, '单选题', '[{"key":"A","text":"保证接口唯一性的命名方案","scores":{"score":0}},{"key":"B","text":"接口中消息模式、格式和协议","scores":{"score":1}},{"key":"C","text":"接口中所接收的数据格式","scores":{"score":0}},{"key":"D","text":"接口消息适用语境","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":36,"correctOptionKey":"B","explanation":"接口标准化是对接口中消息的格式、模式和协议的标准化。它不是要将接口格式化为参数化操作的集合，而是关注输入输出的消息的标准化，它强调当机器在网络中互连时，标准的消息模式、格式、协议的重要性。这也是因特网（IP, UDP,TCP,SNMP, 等等）和 Web（HTTP, HTML, 等等）标准的主要做法。为了获得更广泛的语义，有必要在一个单一通用的消息格式语境中标准化消息模式。这就是 XML 的思想。XML 提供了一种统一的数据格式。\\n\\nOMG接口定义语言 IDL 文件包含了六种不同的元素，（37）是一个 IDL 文件最核心的内容，（38）将映射为Java 语言中的包 (Package) 或 c++语言中的命名空间(Namespace)。\\n (37)A.模块定义B.消息结构C.接口描述D.值类型","imageHashValues":[],"fullExplanation":"接口标准化是对接口中消息的格式、模式和协议的标准化。它不是要将接口格式化为参数化操作的集合，而是关注输入输出的消息的标准化，它强调当机器在网络中互连时，标准的消息模式、格式、协议的重要性。这也是因特网（IP, UDP,TCP,SNMP, 等等）和 Web（HTTP, HTML, 等等）标准的主要做法。为了获得更广泛的语义，有必要在一个单一通用的消息格式语境中标准化消息模式。这就是 XML 的思想。XML 提供了一种统一的数据格式。\\n\\nOMG接口定义语言 IDL 文件包含了六种不同的元素，（37）是一个 IDL 文件最核心的内容，（38）将映射为Java 语言中的包 (Package) 或 c++语言中的命名空间(Namespace)。\\n (37)A.模块定义B.消息结构C.接口描述D.值类型"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

