INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q040', '应用系统构建中可以采用多种不同的技术，（39）可以将软件某种形式的描述转换为更高级的抽象表现形式，而利用这些获取的信息，（40）能够对现有系统进行修改或重构，从而产生系统的一个新版本。
(39)A.逆向工程（(Reverse Engineering)B.系统改进 (System Improvement)
 C.设计恢复 (DesignRecovery )D.再工程 (Re-engineering)', 40, '单选题', '[{"key":"A","text":"逆向工程（(Reverse Engineering)","scores":{"score":1}},{"key":"B","text":"系统改进 (System Improvement)","scores":{"score":0}},{"key":"C","text":"设计恢复 (Design Recovery )","scores":{"score":0}},{"key":"D","text":"再工程 (Re-engineering)","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":40,"correctOptionKey":"A","explanation":"所谓软件的逆向工程就是分析已有的程序，寻求比源代码更高级的抽象表现形式。一般认为，凡是在软件生命周期内将软件某种形式的描述转换成更为抽象形式的活动都可称为逆向工程。与之相关的概念是：重构（restructuring），指在同一抽象级别上转换系统描述形式；设计恢复（design recovery)，指借助工具从已有程序中抽象出有关数据设计、总体结构设计和过程设计的信息（不一定是原设计）；再工程（re-engineering），也称修复和改造工程，它是在逆向工程所获信息的基础上修改或重构已有的系统，产生系统的一个新版本。","imageHashValues":[],"fullExplanation":"所谓软件的逆向工程就是分析已有的程序，寻求比源代码更高级的抽象表现形式。一般认为，凡是在软件生命周期内将软件某种形式的描述转换成更为抽象形式的活动都可称为逆向工程。与之相关的概念是：重构（restructuring），指在同一抽象级别上转换系统描述形式；设计恢复（design recovery)，指借助工具从已有程序中抽象出有关数据设计、总体结构设计和过程设计的信息（不一定是原设计）；再工程（re-engineering），也称修复和改造工程，它是在逆向工程所获信息的基础上修改或重构已有的系统，产生系统的一个新版本。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q041', '系统移植也是系统构建的一种实现方法，在移植工作中，（41）需要最终确定移植方法。', 41, '单选题', '[{"key":"A","text":"计划阶段","scores":{"score":1}},{"key":"B","text":"准备阶段","scores":{"score":0}},{"key":"C","text":"转换阶段","scores":{"score":0}},{"key":"D","text":"验证阶段","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":41,"correctOptionKey":"A","explanation":"移植工作大体上分为计划阶段、准备阶段、转换阶段、测试阶段、验证阶段。\\n1、计划阶段，在计划阶段，要进行现有系统的调查整理，从移植技术、系统内容（是否进行系统提炼等）、系统运行三个方面，探讨如何转换成新系统，决定移植方法，确立移植工作体制及移植日程。\\n2、准备阶段，在准备阶段要进行移植方面的研究，准备转换所需的资料。该阶段的作业质量将对以后的生产效率产生很大的影响。\\n3、转换阶段，这一阶段是将程序设计和数据转换成新机器能根据需要工作的阶段。提高转换工作的精度，减轻下一阶段的测试负担是提高移植工作效率的基本内容。\\n4、测试阶段，这一阶段是进行程序单元、工作单元测试的阶段。在本阶段要核实程序能否在新系统中准确地工作。所以，当有不能准确工作的程序时，就要回到转换阶段重新工作。\\n5、验证阶段，这是测试完的程序使新系统工作，最后核实系统，准备正式运行的阶段。","imageHashValues":[],"fullExplanation":"移植工作大体上分为计划阶段、准备阶段、转换阶段、测试阶段、验证阶段。\\n1、计划阶段，在计划阶段，要进行现有系统的调查整理，从移植技术、系统内容（是否进行系统提炼等）、系统运行三个方面，探讨如何转换成新系统，决定移植方法，确立移植工作体制及移植日程。\\n2、准备阶段，在准备阶段要进行移植方面的研究，准备转换所需的资料。该阶段的作业质量将对以后的生产效率产生很大的影响。\\n3、转换阶段，这一阶段是将程序设计和数据转换成新机器能根据需要工作的阶段。提高转换工作的精度，减轻下一阶段的测试负担是提高移植工作效率的基本内容。\\n4、测试阶段，这一阶段是进行程序单元、工作单元测试的阶段。在本阶段要核实程序能否在新系统中准确地工作。所以，当有不能准确工作的程序时，就要回到转换阶段重新工作。\\n5、验证阶段，这是测试完的程序使新系统工作，最后核实系统，准备正式运行的阶段。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

