VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q042', '软件确认测试也称为有效性测试，主要验证（42）。确认测试计划通常是在需求分析阶段完成的。根据用户的参与程度不同，软件确认测试通常包括（43）。', 42, '单选题', '[{"key":"A","text":"系统中各个单元模块之间的协作性","scores":{"score":0}},{"key":"B","text":"软件与硬件在实际运行环境中能否有效集成","scores":{"score":0}},{"key":"C","text":"软件功能、性能及其它特性是否与用户需求一致","scores":{"score":1}},{"key":"D","text":"程序模块能否正确实现详细设计说明中的功能、性能和设计约束等要求","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":42,"correctOptionKey":"C","explanation":"软件确认测试一种针对需求的测试，是用户参与的测试。它主要验证软件功能、性能及其它特性是否与用户需求一致。\\n软件确认测试包括：内部确认测试、Alpha、Beta和验收测试。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
