INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q046', '在基于体系结构的软件设计方法中，采用（44）来描述软件架构，采用（45）但来描述功能需求，采用（46）来描述质量需求。', 46, '单选题', '[{"key":"A","text":"连接件","scores":{"score":0}},{"key":"B","text":"用例","scores":{"score":0}},{"key":"C","text":"质量场景","scores":{"score":1}},{"key":"D","text":"质量属性","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":46,"correctOptionKey":"C","explanation":"根据基于软件架构的设计的定义，基于软件架构的设计（Architecture Based Software Development，ABSD）强调由商业、质量和功能需求的组合驱动软件架构设计。它强调采用视角和视图来描述软件架构，采用用例和质量属性场景来描述需求。进一步来说，用例描述的是功能需求，质量属性场景描述的是质量需求（或侧重于非功能需求）。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q047', '体系结构文档化有助于辅助系统分析人员和程序员去实现体系结构。体系结构文档化过程的主要输出包括（47）。', 47, '单选题', '[{"key":"A","text":"体系结构规格说明、测试体系结构需求的质量设计说明书","scores":{"score":1}},{"key":"B","text":"质量属性说明书、体系结构描述","scores":{"score":0}},{"key":"C","text":"体系结构规格说明、软件功能需求说明","scores":{"score":0}},{"key":"D","text":"多视图体系结构模型、体系结构验证说明","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":47,"correctOptionKey":"A","explanation":"体系结构文档化过程的主要输出结果是体系结构规格说明和测试体系结构需求的质量设计说明书这两个文档。软件体系结构的文档要求与软件开发项目中的其他文档是类似的。文档的完整性和质量是软件体系结构成功的关键因素。文档要从使用者的角度进行编写，必须分发给所有与系统有关的开发人员，且必须保证开发者手上的文档是最新的。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q048', '软件架构风格描述某一特定领域中的系统组织方式和惯用模式，反映了领域中众多系统所共有的（48）特征。对于语音识别、知识推理等问题复杂、解空间很大、求解过程不确定的这一类软件系统，通常会采用（49）架构风格。对于因数据输入某个构件，经过内部处理，产生数据输出的系统，通常会采用（50）架构风格。', 48, '单选题', '[{"key":"A","text":"语法和语义","scores":{"score":0}},{"key":"B","text":"结构和语义","scores":{"score":1}},{"key":"C","text":"静态和动态","scores":{"score":0}},{"key":"D","text":"行为和约束","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":48,"correctOptionKey":"B","explanation":"体系结构风格反映了领域中众多系统所共有的结构和语义特性，并指导如何将各个模块和子系统有效地组织成一个完整的系统。对软件体系结构风格的研究和实践促进对设计的重用，一些经过实践证实的解决方案也可以可靠地用于解决新的问题。例如，如果某人把系统描述为客户/服务器模式，则不必给出设计细节，我们立刻就会明白系统是如何组织和工作的。\\n语音识别是黑板风格的经典应用场景。\\n输入某个构件，经过内部处理，产生数据输出的系统，正是管道-过滤器中过滤器的职能，把多个过滤器使用管道相联的风格为管道-过滤器风格。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

