    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q051', '某公司拟开发一个VIP管理系统，系统需要根据不同商场活动，不定期更新VIP会员的审核标准和VIP折扣系统。针对上述需求，采用（51）架构风格最为合适。', 51, '单选题', '[{"key":"A","text":"规则系统","scores":{"score":1}},{"key":"B","text":"过程控制","scores":{"score":0}},{"key":"C","text":"分层","scores":{"score":0}},{"key":"D","text":"管道-过滤器","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":51,"correctOptionKey":"A","explanation":"","imageHashValues":[]}')
