INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q052', '某公司拟开发一个新闻系统，该系统可根据用户的注册兴趣，向用户推送其感兴趣的新闻内容，该系统应该采用（52）架构风格最为合适。', 52, '单选题', '[{"key":"A","text":"事件驱动系统","scores":{"score":1}},{"key":"B","text":"主程序-子程序","scores":{"score":0}},{"key":"C","text":"黑板","scores":{"score":0}},{"key":"D","text":"管道-过滤器","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":52,"correctOptionKey":"A","explanation":"根据题目的意思，用户会注册自己的兴趣，然后系统也会把新闻按兴趣分类，如果某个新闻事件发生，可以通过事件来触发推送动作，将新闻推送给对其感兴趣的用户。这是典型的事件驱动系统应用场景。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q053', '系统中的构件和连接件都有一个顶部和一个底部，构件的顶部应连接到某连接件的底部，构件的底部则应连接到某连接的顶部，构件和构件之间不允许直接连接，连接件直接连接时，必须由其中一个的底部连接到另一个的顶部。上述构件和连接件的组织规则描述的是（53）架构风格。', 53, '单选题', '[{"key":"A","text":"管道-过滤器","scores":{"score":0}},{"key":"B","text":"分层系统","scores":{"score":0}},{"key":"C","text":"C2","scores":{"score":1}},{"key":"D","text":"面向对象","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":53,"correctOptionKey":"C","explanation":"C2体系结构风格可以概括为：通过连接件绑定在一起按照一组规则运作的并行构件网络。C2风格中的系统组织规则如下。\\n①系统中的构件和连接件都有一个顶部和一个底部。\\n②构件的顶部应连接到某连接件的底部，构件的底部则应连接到某连接件的顶部。而构件与构件之间的直接连接是不允许的。\\n③一个连接件可以和任意数目的其他构件和连接件连接。\\n④当两个连接件进行直接连接时，必须由其中一个的底部到另一个的顶部。\\n 【img:503138e54adbf4733f3d040fc75710105696f0d56574e9e7f7d179703931d4de】","imageHashValues":["503138e54adbf4733f3d040fc75710105696f0d56574e9e7f7d179703931d4de"],"fullExplanation":"C2体系结构风格可以概括为：通过连接件绑定在一起按照一组规则运作的并行构件网络。C2风格中的系统组织规则如下。\\n①系统中的构件和连接件都有一个顶部和一个底部。\\n②构件的顶部应连接到某连接件的底部，构件的底部则应连接到某连接件的顶部。而构件与构件之间的直接连接是不允许的。\\n③一个连接件可以和任意数目的其他构件和连接件连接。\\n④当两个连接件进行直接连接时，必须由其中一个的底部到另一个的顶部。\\n 【img:503138e54adbf4733f3d040fc75710105696f0d56574e9e7f7d179703931d4de】"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

