    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q065', '第65题', 65, '单选题', '[{"key":"A","text":"双主机系统，即使外网被黑客攻击瘫痪也无法影响到内网","scores":{"score":0}},{"key":"B","text":"可以防止外部主动攻击","scores":{"score":0}},{"key":"C","text":"采用专用硬件控制技术保证内外网的实时连接","scores":{"score":1}},{"key":"D","text":"设备对外网的任何响应都是对内网用户请求的应答","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":65,"correctOptionKey":"C","explanation":"王某买了一幅美术作品原件，则他享有该美术作品的（66）。\\n (66)A.著作权B.所有权C.展览权D.所有权与其展览权\\n【答案】D\\n【解析】","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
