INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q067', '甲、乙软件公司同日就其财务软件产品分别申请"用友"和"用有"商标注册。两财务软件相似，且甲、乙第一次使用"用友"和"用有"商标时间均为2015年7月12日。此情形下，（67）能获准注册。', 67, '单选题', '[{"key":"A","text":"“用友”","scores":{"score":0}},{"key":"B","text":"“用友”与“用有”都","scores":{"score":0}},{"key":"C","text":"“用有”","scores":{"score":0}},{"key":"D","text":"由甲、乙抽签结果确定谁","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":67,"correctOptionKey":"D","explanation":"某人持有盗版软件，但不知道该软件是盗版的，该软件的提供者不能证明其提供的复制品有合法来源。此情况下，则该软件的（68）应承担法律责任。\\n (68)A.持有者B.持有者和提供者均\\n C.提供者D.持有者和提供者均不\\n【答案】C\\n【解析】\\n\\n某工程包括A、B、C、D四个作业，其衔接关系、正常进度下所需天数和所需直接费用、赶工进度下所需的最少天数和每天需要增加的直接费用见下表。该工程的间接费用为每天5万元。据此，可以估算出完成该工程最少需要费用（69）万元，以此最低费用完成该工程需要（70）天。\\n 【img:91037eeb3ea8bdbd670cf7c1bfc5df36c6688bd5a5c540a14c82e4b3a5db56ae】 \\n (69)A.106B.108C.109D.115","imageHashValues":["91037eeb3ea8bdbd670cf7c1bfc5df36c6688bd5a5c540a14c82e4b3a5db56ae"],"fullExplanation":"某人持有盗版软件，但不知道该软件是盗版的，该软件的提供者不能证明其提供的复制品有合法来源。此情况下，则该软件的（68）应承担法律责任。\\n (68)A.持有者B.持有者和提供者均\\n C.提供者D.持有者和提供者均不\\n【答案】C\\n【解析】\\n\\n某工程包括A、B、C、D四个作业，其衔接关系、正常进度下所需天数和所需直接费用、赶工进度下所需的最少天数和每天需要增加的直接费用见下表。该工程的间接费用为每天5万元。据此，可以估算出完成该工程最少需要费用（69）万元，以此最低费用完成该工程需要（70）天。\\n 【img:91037eeb3ea8bdbd670cf7c1bfc5df36c6688bd5a5c540a14c82e4b3a5db56ae】 \\n (69)A.106B.108C.109D.115"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q070', '第70题', 70, '单选题', '[{"key":"A","text":"7","scores":{"score":1}},{"key":"B","text":"9","scores":{"score":0}},{"key":"C","text":"10","scores":{"score":0}},{"key":"D","text":"12","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":70,"correctOptionKey":"A","explanation":"本题是项目管理中，时间管理的关键路径问题。先将题目中的各个结点依赖关系画出来，如图所示：\\n 【img:5aca4e78f6cbe5c26f6e31112059e65f9a80325d4cc75a8392f68922d03fa3d0】 \\n通过结点依赖图，结合题目正常进度所需天数很容易看出ACD为关键路径。关键路径长度为12天。但这样得到的就是最短工期与最少花费吗？不是。因为题目指出间接花费是每天5万元，而赶工每天的费用仅2-4万。此时赶工完成部分任务，既能缩短工期，又能降低费用，是合适的解决方案，经过分析，赶工方案为：\\nA赶工2天，B赶工1天，D赶工3天。此时关键路径长度为7天，总花费为106万。\\n\\nThe architecture design specifies the overall architecture and the placement of software and hardware that will be used. Architecture design is a very complex process that is often left to experienced architecture designers and consultants. The first step is to refine the (71) into more detailed requirements that are then employed to help select the architecture to be used and the software components to be placed on each device. In a (72), one also has to decide whether to use a two-tier, three-tier,or n-tier architecture. Then the requirements and the architecture design are used to develop the hardware and software specification. There are four primary types of nonfunctional requirements that can be important in designing the architecture. (73) specify the operating environment(s) in which the system must perform and how those may change over time. (74) focus on the nonfunctional requirements issues such as response time,capacity,and reliability. (75) are the abilities to protect the information system from disruption and data loss, whether caused by an intentional act. Cultural and political requirements are specific to the countries in which the system will be used.","imageHashValues":["5aca4e78f6cbe5c26f6e31112059e65f9a80325d4cc75a8392f68922d03fa3d0"],"fullExplanation":"本题是项目管理中，时间管理的关键路径问题。先将题目中的各个结点依赖关系画出来，如图所示：\\n 【img:5aca4e78f6cbe5c26f6e31112059e65f9a80325d4cc75a8392f68922d03fa3d0】 \\n通过结点依赖图，结合题目正常进度所需天数很容易看出ACD为关键路径。关键路径长度为12天。但这样得到的就是最短工期与最少花费吗？不是。因为题目指出间接花费是每天5万元，而赶工每天的费用仅2-4万。此时赶工完成部分任务，既能缩短工期，又能降低费用，是合适的解决方案，经过分析，赶工方案为：\\nA赶工2天，B赶工1天，D赶工3天。此时关键路径长度为7天，总花费为106万。\\n\\nThe architecture design specifies the overall architecture and the placement of software and hardware that will be used. Architecture design is a very complex process that is often left to experienced architecture designers and consultants. The first step is to refine the (71) into more detailed requirements that are then employed to help select the architecture to be used and the software components to be placed on each device. In a (72), one also has to decide whether to use a two-tier, three-tier,or n-tier architecture. Then the requirements and the architecture design are used to develop the hardware and software specification. There are four primary types of nonfunctional requirements that can be important in designing the architecture. (73) specify the operating environment(s) in which the system must perform and how those may change over time. (74) focus on the nonfunctional requirements issues such as response time,capacity,and reliability. (75) are the abilities to protect the information system from disruption and data loss, whether caused by an intentional act. Cultural and political requirements are specific to the countries in which the system will be used."}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2017H2_GK', 'RK_SA_ARCH_2017H2_GK_Q071', '第71题', 71, '单选题', '[{"key":"A","text":"functional requirements","scores":{"score":0}},{"key":"B","text":"nonfunctional requirements","scores":{"score":1}},{"key":"C","text":"system constraint","scores":{"score":0}},{"key":"D","text":"system operational environment","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":71,"correctOptionKey":"B","explanation":"架构设计指定了将要使用的软件和硬件的总体架构和布局。 架构设计是一个非常复杂的过程，往往留给经验丰富的架构设计师和顾问。 第一步是将（71）细化为更详细的要求，然后用于帮助选择要使用的体系结构以及要放置在每个设备上的软件组件。\\n在（72）中，还必须决定是使用两层，三层还是n层架构。 然后使用需求和体系结构设计来开发硬件和软件规范。 有四种主要的非功能需求类型可能在设计架构时非常重要。 （73）指定系统必须执行的操作环境以及这些操作环境如何随时间变化。 （74）注重非功能性要求是特定于系统将被使用的国家。\\n在（72）中，还必须决定是使用两层，三层还是n层架构。 然后使用需求和体系结构设计来开发硬件和软件规范。 有四种主要的非功能需求类型可能在设计架构时非常重要。 （73）指定系统必须执行的操作环境以及这些操作环境如何随时间变化。 （74）侧重于非功能性需求问题，如响应时间，容量和可靠性。 （75）是否有能力保护信息系统免受故意行为造成的破坏和数据丢失。 文化和政治要求是特定于系统将被使用的国家。\\n71 A functional requirements（功能需求） B nonfunctional requirements （非功能需求）\\nC system constraint （系统约束） D system operational environment （系统操作环境）\\n72 A client-based architecture （基于客户端的架构）\\nB server-based architecture（基于服务器的架构）\\nC network architecture （网络架构）\\nD client-server architecture （客户端 - 服务器架构）\\n73 A operational requirements （操作要求）\\nB speed requirements （速度要求）\\nC Access control requirements （访问控制要求）\\nD customization requirements （用户要求）\\n74 A environment requirements （环境要求）\\nB Maintainability requirements （可维护性要求）\\nC performance requirements （性能要求）\\nD virus control requirements（病毒控制要求）\\n75 A safety requirements （安全要求）\\nB security requirements（安全要求）\\nC Data management requirements （数据管理要求）\\nD system requirements（系统要求）\\n\\n试题一\\n阅读以下关于软件架构评估的叙述，在答题纸上回答问题1和问题2.\\n【说明】\\n某单位为了建设健全的公路桥梁养护管理档案，拟开发一套公路桥梁在线管理系统。在系统的需求分析与架构设计阶段，用户提出的需求、质量属性描述和架构特性如 下:\\n(a) 系统用户分为高级管理员、数据管理员和数据维护员等三类；\\n(b) 系统应该具备完善的安全防护措施，能够对黑客的攻击行为进行检测与防御；\\n(c) 正常负载情况下，系统必须在 0.5 秒内对用户的查询请求进行响应；\\n(d) 对查询请求处理时间的要求将影响系统的数据传输协议和处理过程的设计；\\n(e) 系统的用户名不能为中文，要求必须以字母开头，长度不少于5个字符；\\n(f) 更改系统加密的级别将对安全性和性能产生影响；\\n(g) 网络失效后，系统需要在 10 秒内发现错误并启用备用系统；\\n(h) 查询过程中涉及到的桥梁与公路的实时状态视频传输必须保证画面具有1024*768的分辨率， 40帧 /秒的速率；\\n(i) 在系统升级时，必须保证在 10 人月内可添加一个新的消息处理中间件；\\n(j) 系统主站点断电后，必须在 3 秒内将请求重定向到备用站点；\\n(k) 如果每秒钟用户查询请求的数量是 10 个，处理单个请求的时间为 30 毫秒，则系统应保证在 1秒内完成用户的查询请求；\\n(l) 对桥梁信息数据库的所有操作都必须进行完整记录；\\n(m) 更改系统的 Web 界面接口必须在 4 人周内完成；\\n(n) 如果\\"养护报告生成\\"业务逻辑的描述尚未达成共识，可能导致部分业务功能 模块规则的矛盾，影响系统的可修改性\\n(O) 系统必须提供远程调试接口，并支持系统的远程调试。\\n在对系统需求，质量属性描述和架构特性进行分析的基础上，系统的架构师给出了三个候选的架构设计方案，公司目前正在组织系统开发的相关人员对系统架构进行评估。\\n \\n【问题1】 (12 分)\\n在架构评估过程中，质量属性效用树 (utility tree) 是对系统质量属性进行识别和优先级排序的重要工具。请给出合适的质量属性，填入图 1-1 中 (1)、(2) 空白处；并选择题干描述的 (a)~(o) ，填入(3) ~(6) 空白处，完成该系统的效用树。\\n 【img:5537c0e0069e2a77bebacac05c4a2959f1b193a58f3188e3e41755d94e29c9fe】 \\n（1）安全性 \\n（2）可修改性 \\n（3）（h） \\n（4）（l）\\n（5）（j） \\n（6）（m） \\n\\n【问题2】(13 分)\\n在架构评估过程中，需要正确识别系统的架构风险、敏感点和权衡点，并进行合理的架构决策。请用 300 字以内的文字给出系统架构风险、敏感点和权衡点的定义，并从题干(a) ~(o) 中分别选出 1个对系统架构风险、敏感点和权衡点最为恰当的描述。\\n\\n系统架构风险是指架构设计中潜在的、存在问题的架构决策所带来的隐患。\\n敏感点是指为了实现某种特定的质量属性，一个或多个构件所具有的特性。\\n权衡点是影响多个质量属性的特性，是多个质量属性的敏感点。\\n风险点：（n）\\n敏感点：（d）\\n权衡点：（f）\\n试题二\\n阅读以下关于软件系统设计的叙述，在答题纸上回答问题1至问题3.\\n【说明】\\n某软件企业受该省教育部门委托建设高校数字化教育教学资源共享平台，实现以众筹众创的方式组织省内普通高校联合开展教育教学资源内容建设，实现全省优质教学资源整合和共享。该资源共享平台的主要功能模块包括：\\n(1)统一身份认证模块：提供统一的认证入口，为平台其他核心业务模块提供用户管理、身份认证、权限分级和单点登录等功能；\\n(2) 共享资源管理模块：提供教学资源申报流程服务，包括了资源申报、分类定制、资料上传、资源审核和资源发布等功能；\\n(3)共享资源展示模块：提供教育教学共享资源的展示服务，包括资源导航、视频点播、资源检索、分类展示、资源评价和推荐等功能；\\n(4) 资源元模型管理模块：依据资源类型提供共享资源的描述属性、内容属性和展示属性，包括共享资源统一标准和规范、资源加工和在线编辑工具、数字水印和模板定制等功能；\\n(5) 系统综合管理模块：提供系统管理和维护服务，包括系统配置、数据备份恢复、资源导入导出和统计分析等功能。\\n项目组经过分析和讨论，决定采用基于Java EE的MVC 模式设计资源共享平台的软件架构，如图2-1所示。\\n 【img:188651f8d8bb093f121e84e9cc3cad182b33c9354ec73282da794392c6e501c4】 \\n图2-1 资源共享平台软件架构\\n \\n【问题1】(9 分)\\nMVC架构中包含哪三种元素，它们的作用分别是什么?请根据图 2-1 所示架构将JavaEE 中 JSP、Servlet、Service、JavaBean、DAO 五种构件分别填入空 (1)~（5） 所示位置。\\n \\nMVC架构包含：视图、控制器、模型\\n视图（View）：视图是用户看到并与之交互的界面。视图向用户显示相关的数据，并能接收用户的输入数据，但是它并不进行任何实际的业务处理。\\n控制器（Controller）：控制器接受用户的输入并调用模型和视图去完成用户的需求。该部分是用户界面与Model的接口。一方面它解释来自于视图的输入，将其解释成为系统能够理解的对象，同时它也识别用户动作，并将其解释为对模型特定方法的调用；另一方面，它处理来自于模型的事件和模型逻辑执行的结果，调用适当的视图为用户提供反馈。\\n模型（Model）：模型是应用程序的主体部分。模型表示业务数据和业务逻辑。一个模型能为多个视图提供数据。\\n（1）JSP （2）Servlet （3）Service （4）JavaBean （5）DAO\\n【问题2】(6 分)\\n项目组架构师王工提出在图2-1所示架构设计中加入EJB构件，采用企业级JavaEE架构开发资源共享平台。请说明EJB构件中的Bean (构件)分为哪三种类型，每种类型Bean的职责是什么。\\n \\nEJB中的Bean分三种类型：Session Bean、Entity Beans 和 Message-Driven Bean。\\nSession Bean的职责是：维护一个短暂的会话\\nEntity Beans 的职责是：维护一行持久稳固的数据\\nMessage-Driven Bean的职责是：异步接受消息 \\n\\n【问题3】 (10分)\\n如果采用王工提出的企业 JavaEE架构，请说明下列(a)-(e) 所给出的业务功能构件中，有状态和无状态构件分别包括哪些。\\n（a）Identification Bean (身份认证构件)\\n（b）ResPublish Bean(资源发布构件)\\n（c）ResRetrieval Bean(资源检索构件)\\n（d）OnlineEdit Bean(在线编辑构件)\\n（e）Statistics Bean(统计分析构件)\\n\\n有状态：（a）、（d）\\n无状态：（b）、（c）、（e）\\n\\n试题三\\n阅读以下关于机器人操作系统架构的描述，回答问题1至问题3\\n【说明】\\n随着人工智能技术的发展，工业机器人已成为当前工业界的热点研究对象。某宇航设备公司为了扩大业务范围，决策层研究决定准备开展工业机器人研制新业务。公司将论证工作交给了软件架构师王工，王工经过分析和调研，从机器人市场现状、领域需求、组成及关键技术和风险分析等方面开展了综合论证。论证报告指出：首先，为了保障本公司机器人研制的持续性，应根据领域需求选择一种适应的设计架构；其次，为了规避风险，公司的研制工作不能从零开始，应该采用国际开源社区所提供机器人操作系统 (Robot Operating System ，ROS)作为机器人开发的基本平台。\\n在讨论会上，架构师李工提出不同意见，他认为公司针对宇航领域已开发了某款嵌 入式实时操作系统，且被多种宇航装备使用，可靠性较高。因此应该采用现有架构体系作为机器人的开发平台。会上王工说明了机器人操作系统与该款操作系统的差别，要沿用需要进行改造，技入较大。经过激烈讨论，公司领导同意了王工采用 ROS的意见。\\n \\n【问题1】(5分)\\n王工拟采用的ROS具有分布式进程框架，以点对点设计以及服务和节点管理器方式， 使得执行程序可以各自独立地设计，松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组，因而可以容易地分享和发布。请用400字以内文字说明ROS与嵌入式实时操作系统的共同点，以及在实时性和任务通信方式两个方面的差异。\\n \\nROS与嵌入式实时操作系统的共同点：\\n（1）系统微型化\\n（2）系统专用性强\\n（3）软硬件依赖性强\\n（4）系统资源受限\\nROS与嵌入式实时操作系统的差异：\\n实性性：ROS弱于嵌入式实时操作系统\\n通信方式：ROS的通信方式较为丰富，嵌入式实时操作系统通信方式单一。\\n【问题2】(10分)\\nROS为应用程序间通信提供了主题(Topic) 、服务 (Service)和动作 (Action) 三种消息通信方式，每种通信方式都有其特点。请将以下给出的三类通信的主要特点填入表3-1中(1)-(5) 的空白处，将答案写在答题纸上。\\n(a) 适合用于传输传感器信息〈数据流)\\n(b) 能够知道是否调用成功\\n(c) 一对多模式\\n(d) 有握手信号\\n(e) 服务执行完会有反馈\\n(f) 可以监控长时间执行的进程\\n(g) 较复杂\\n(h) 可能让系统过载(数据太多)\\n(i) 服务执行完之前，程序会等待\\n(j) 建立通信较慢\\n(k) 可能丢失数据\\n 【img:44d8dd06dfdffa7baad0be576dfea6fa4d278662ac396ae0c6fd158f6524140b】 \\n（1）（2）（c）（k） \\n（3）（4）（f）（i）\\n（5）（j） \\n【问题3】(10分)\\nROS 的架构定义了ROS系统由多个各自独立的节点(组件〉组成，并且各个节点之间可以通过发布/订阅(Publish/Subscribe )消息模型进行通信。图 3-1给出一个简单机器人结构实例，请根据以下文字描述，补充图3-1 中(1)~(5) 处空白，将答案写在答题纸上。\\n\\"机器人开始阶段，所有节点都要注册 (Registration) 到Master上，注册后，摄像头节点声明它要发布(Publish)一个叫做/image_data的消息。另外两个节点（图像处理处理节点和图像显示节点）声明它们需要订阅( Subscribe) 这个/image_data消息。因此， 一旦摄像头节点收到相机发送的数据(Data)，就立即将数据/image_data直接发送到另外两个节点。\\n 【img:d04dc47d94011e8c6647e279a56893f45e840e488274f9ab65fb5d0075eb818f】 \\n（1）Registration （2）Data （3）Publish （4）Subscribe （5）Subscribe\\n\\n试题四\\n阅读以下关于数据库设计的叙述，在答题纸上回答问题1至问题3。\\n【说明】\\n某制造企业为拓展网上销售业务，委托某软件企业开发一套电子商务网站。初期仅解决基本的网上销售、订单等功能需求。该软件企业很快决定基于.NET平台和SQL Server数据库进行开发，但在数据库访问方式上出现了争议。王工认为应该采用程序在 线访问的方式访问数据库；而李工认为本企业内部程序员缺乏数据库开发经验，而且应用筒单，应该采用ORM (对象关系映射)方式。最终经过综合考虑，该软件企业采用了李工的建议。\\n随着业务的发展，该电子商务网站逐渐发展成一个通用的电子商务平台，销售多家制造企业的产品，电子商务平台的功能也日益复杂。目前急需对该电子商务网站进行改造，以支持对多种异构数据库平台的数据访问，同时满足复杂的数据管理需求。该软件企业针对上述需求，对电子商务网站的架构进行了重新设计，新增加了数据访问层，同时采用工厂设计模式解决异构数据库访问的问题。新设计的系统架构如图 4-1 所示。\\n 【img:ede6baf2a516a682293c9fa0812413e5152be79849d98e1833c0562af776ce55】 \\n \\n【问题1】 (9分)\\n请用300字以内的文字分别说明数据库程序在线访问方式和ORM方式的优缺点，说明该软件企业采用ORM的原因。\\n数据库程序在线访问方式优点：\\n1、性能比直接SQL好\\n2、可以处理复杂查询语句\\n数据库程序在线访问方式缺点：\\n1、要求程序员懂SQL语句\\n2、修改与维护相对困难\\nORM优点：\\n1、使用ORM可以大大降低学习和开发成本。\\n2、程序员不用再写SQL来进行数据库操作。\\n3、减少程序的代码量。\\n4、降低由于SQL代码质量差而带来的影响。\\nORM缺点\\n1、不太容易处理复杂查询语句。\\n2、性能较直接用SQL差。\\n本题中的场景之所以选择ORM，主要考虑的是程序缺数据库开发经验，这样SQL语句质量有很大风险。同时学习成本很高。此外应用简单，不也担心ORM对性能的影响。\\n【问题2】(9分)\\n请用100字以内的文字说明新体系架构中增加数据访问层的原因。请根据图4-1所示，填写图中空白处(1) - (3)。\\n增加数据访问层的原因：\\n（1）由于涉及到多种异构数据库平台，数据访问复杂性增加，不宜与业务逻辑混合在一起\\n（2）数据管理变复杂之后，需要使用的代码量增加，分单独层次有利于让逻辑更清晰。\\n（3）业务逻辑应以相同的方式应对异构的数据库，此时需要单独的数据访问层屏蔽差异性。\\n（1）执行业务逻辑 （2）工厂层 （3）数据访问接口层\\n【问题3】(7分) \\n应用程序设计中，数据库访问需要良好的封装性和可维护性，因此经常使用工厂设计模式来实现对数据库访问的封装。请解释工厂设计模式，并说明其优点和应用场景:；请解释说明工厂模式在数据访问层中的应用。\\n工厂模式分抽象工厂与工厂方法，题目中的场景适合采用抽象工厂设计模式。\\n抽象工厂设计模式提供一个接口，可以创建一系列相关或相互依赖的对象，而无需指定它们具体的类。其优点是可以非常方便的创建一系列的对象，其使用场景也是创建系列对象的情况。在本题中，可以针对Oracle、MySQL、SQLServer分别建立抽象工厂，若指定当前工厂为Oracle工厂，则创建出来的数据库连接，数据集等一系列的对象都是符合Oracle操作要求的。这样便于数据库之间的切换。\\n\\n试题五\\n阅读以下关于Web系统架构设计的叙述，在答题纸上回答问题1至问题3.\\n【说明】\\n某电子商务企业因发展良好，客户量逐步增大，企业业务不断扩充，导致其原有的B2C商品交易平台己不能满足现有业务需求。因此，该企业委托某软件公司重新开发一套商品交易平台。该企业要求新平台应可适应客户从手机、平板设备、电脑等不同终端设备访问系统，同时满足电商定期开展\\"秒杀\\"、\\"限时促销\\"等活动的系统高并发访问量的需求。面对系统需求，软件公司召开项目组讨论会议，制定系统设计方案。讨论会议上，王工提出可以应用响应式Web设计满足客户从不同设备正确访问系统的需求。 同时，采用增加镜像站点、CDN 内容分发等方式解决高并发访问量带来的问题。李工在王工的提议上补充，仅仅依靠上述外网加速技术不能完全解决高用户并发访问问题，如果访问量持续增加，系统仍存在崩溃可能。李工提出应同时结合负载均衡、缓存服务器、Web应用服务器、分布式文件系统、分布式数据库等方法设计系统架构。经过项目组讨论，最终决定综合王王和李工的思路，完成新系统的架构设计。\\n \\n【问题1】(5分)\\n请用200字以内的文字描述什么是\\"响应式 Web 设计\\"，并列举2个响应式Web设计的实现方式。\\n响应式web设计是指我们设计与开发的页面可以根据用户的行为和不同的设备环境做出相应的响应来调整页面的布局，以提供用户可感知的、流畅的阅读和操作体验。\\n实现方式：\\n（1）流式布局\\n（2）弹性布局加媒体查询\\n【问题2】(16 分)\\n综合王工和李工的提议，项目组完成了新商品交易平台的系统架构设计方案。新系统架构图如图5-1所示。请从选项 (a) - (j) 中为架构图中(1) - (8) 处空白选择相应的内容，补充支持高并发的Web应用系统架构设计图。\\n 【img:36a9998114a9e60f99c54bc735f1c58767e68629017deed4ecbb06c0b045394e】 \\n(a) Web 应用层\\n(b) 界面层\\n(c) 负载均衡层\\n(d) CDN 内容分发\\n(e) 主数据库\\n(f) 缓存服务器集群\\n(g) 从数据库\\n(h) ","imageHashValues":["5537c0e0069e2a77bebacac05c4a2959f1b193a58f3188e3e41755d94e29c9fe","188651f8d8bb093f121e84e9cc3cad182b33c9354ec73282da794392c6e501c4","44d8dd06dfdffa7baad0be576dfea6fa4d278662ac396ae0c6fd158f6524140b","d04dc47d94011e8c6647e279a56893f45e840e488274f9ab65fb5d0075eb818f","ede6baf2a516a682293c9fa0812413e5152be79849d98e1833c0562af776ce55","36a9998114a9e60f99c54bc735f1c58767e68629017deed4ecbb06c0b045394e"],"fullExplanation":"架构设计指定了将要使用的软件和硬件的总体架构和布局。 架构设计是一个非常复杂的过程，往往留给经验丰富的架构设计师和顾问。 第一步是将（71）细化为更详细的要求，然后用于帮助选择要使用的体系结构以及要放置在每个设备上的软件组件。\\n在（72）中，还必须决定是使用两层，三层还是n层架构。 然后使用需求和体系结构设计来开发硬件和软件规范。 有四种主要的非功能需求类型可能在设计架构时非常重要。 （73）指定系统必须执行的操作环境以及这些操作环境如何随时间变化。 （74）注重非功能性要求是特定于系统将被使用的国家。\\n在（72）中，还必须决定是使用两层，三层还是n层架构。 然后使用需求和体系结构设计来开发硬件和软件规范。 有四种主要的非功能需求类型可能在设计架构时非常重要。 （73）指定系统必须执行的操作环境以及这些操作环境如何随时间变化。 （74）侧重于非功能性需求问题，如响应时间，容量和可靠性。 （75）是否有能力保护信息系统免受故意行为造成的破坏和数据丢失。 文化和政治要求是特定于系统将被使用的国家。\\n71 A functional requirements（功能需求） B nonfunctional requirements （非功能需求）\\nC system constraint （系统约束） D system operational environment （系统操作环境）\\n72 A client-based architecture （基于客户端的架构）\\nB server-based architecture（基于服务器的架构）\\nC network architecture （网络架构）\\nD client-server architecture （客户端 - 服务器架构）\\n73 A operational requirements （操作要求）\\nB speed requirements （速度要求）\\nC Access control requirements （访问控制要求）\\nD customization requirements （用户要求）\\n74 A environment requirements （环境要求）\\nB Maintainability requirements （可维护性要求）\\nC performance requirements （性能要求）\\nD virus control requirements（病毒控制要求）\\n75 A safety requirements （安全要求）\\nB security requirements（安全要求）\\nC Data management requirements （数据管理要求）\\nD system requirements（系统要求）\\n\\n试题一\\n阅读以下关于软件架构评估的叙述，在答题纸上回答问题1和问题2.\\n【说明】\\n某单位为了建设健全的公路桥梁养护管理档案，拟开发一套公路桥梁在线管理系统。在系统的需求分析与架构设计阶段，用户提出的需求、质量属性描述和架构特性如 下:\\n(a) 系统用户分为高级管理员、数据管理员和数据维护员等三类；\\n(b) 系统应该具备完善的安全防护措施，能够对黑客的攻击行为进行检测与防御；\\n(c) 正常负载情况下，系统必须在 0.5 秒内对用户的查询请求进行响应；\\n(d) 对查询请求处理时间的要求将影响系统的数据传输协议和处理过程的设计；\\n(e) 系统的用户名不能为中文，要求必须以字母开头，长度不少于5个字符；\\n(f) 更改系统加密的级别将对安全性和性能产生影响；\\n(g) 网络失效后，系统需要在 10 秒内发现错误并启用备用系统；\\n(h) 查询过程中涉及到的桥梁与公路的实时状态视频传输必须保证画面具有1024*768的分辨率， 40帧 /秒的速率；\\n(i) 在系统升级时，必须保证在 10 人月内可添加一个新的消息处理中间件；\\n(j) 系统主站点断电后，必须在 3 秒内将请求重定向到备用站点；\\n(k) 如果每秒钟用户查询请求的数量是 10 个，处理单个请求的时间为 30 毫秒，则系统应保证在 1秒内完成用户的查询请求；\\n(l) 对桥梁信息数据库的所有操作都必须进行完整记录；\\n(m) 更改系统的 Web 界面接口必须在 4 人周内完成；\\n(n) 如果\\"养护报告生成\\"业务逻辑的描述尚未达成共识，可能导致部分业务功能 模块规则的矛盾，影响系统的可修改性\\n(O) 系统必须提供远程调试接口，并支持系统的远程调试。\\n在对系统需求，质量属性描述和架构特性进行分析的基础上，系统的架构师给出了三个候选的架构设计方案，公司目前正在组织系统开发的相关人员对系统架构进行评估。\\n \\n【问题1】 (12 分)\\n在架构评估过程中，质量属性效用树 (utility tree) 是对系统质量属性进行识别和优先级排序的重要工具。请给出合适的质量属性，填入图 1-1 中 (1)、(2) 空白处；并选择题干描述的 (a)~(o) ，填入(3) ~(6) 空白处，完成该系统的效用树。\\n 【img:5537c0e0069e2a77bebacac05c4a2959f1b193a58f3188e3e41755d94e29c9fe】 \\n（1）安全性 \\n（2）可修改性 \\n（3）（h） \\n（4）（l）\\n（5）（j） \\n（6）（m） \\n\\n【问题2】(13 分)\\n在架构评估过程中，需要正确识别系统的架构风险、敏感点和权衡点，并进行合理的架构决策。请用 300 字以内的文字给出系统架构风险、敏感点和权衡点的定义，并从题干(a) ~(o) 中分别选出 1个对系统架构风险、敏感点和权衡点最为恰当的描述。\\n\\n系统架构风险是指架构设计中潜在的、存在问题的架构决策所带来的隐患。\\n敏感点是指为了实现某种特定的质量属性，一个或多个构件所具有的特性。\\n权衡点是影响多个质量属性的特性，是多个质量属性的敏感点。\\n风险点：（n）\\n敏感点：（d）\\n权衡点：（f）\\n试题二\\n阅读以下关于软件系统设计的叙述，在答题纸上回答问题1至问题3.\\n【说明】\\n某软件企业受该省教育部门委托建设高校数字化教育教学资源共享平台，实现以众筹众创的方式组织省内普通高校联合开展教育教学资源内容建设，实现全省优质教学资源整合和共享。该资源共享平台的主要功能模块包括：\\n(1)统一身份认证模块：提供统一的认证入口，为平台其他核心业务模块提供用户管理、身份认证、权限分级和单点登录等功能；\\n(2) 共享资源管理模块：提供教学资源申报流程服务，包括了资源申报、分类定制、资料上传、资源审核和资源发布等功能；\\n(3)共享资源展示模块：提供教育教学共享资源的展示服务，包括资源导航、视频点播、资源检索、分类展示、资源评价和推荐等功能；\\n(4) 资源元模型管理模块：依据资源类型提供共享资源的描述属性、内容属性和展示属性，包括共享资源统一标准和规范、资源加工和在线编辑工具、数字水印和模板定制等功能；\\n(5) 系统综合管理模块：提供系统管理和维护服务，包括系统配置、数据备份恢复、资源导入导出和统计分析等功能。\\n项目组经过分析和讨论，决定采用基于Java EE的MVC 模式设计资源共享平台的软件架构，如图2-1所示。\\n 【img:188651f8d8bb093f121e84e9cc3cad182b33c9354ec73282da794392c6e501c4】 \\n图2-1 资源共享平台软件架构\\n \\n【问题1】(9 分)\\nMVC架构中包含哪三种元素，它们的作用分别是什么?请根据图 2-1 所示架构将JavaEE 中 JSP、Servlet、Service、JavaBean、DAO 五种构件分别填入空 (1)~（5） 所示位置。\\n \\nMVC架构包含：视图、控制器、模型\\n视图（View）：视图是用户看到并与之交互的界面。视图向用户显示相关的数据，并能接收用户的输入数据，但是它并不进行任何实际的业务处理。\\n控制器（Controller）：控制器接受用户的输入并调用模型和视图去完成用户的需求。该部分是用户界面与Model的接口。一方面它解释来自于视图的输入，将其解释成为系统能够理解的对象，同时它也识别用户动作，并将其解释为对模型特定方法的调用；另一方面，它处理来自于模型的事件和模型逻辑执行的结果，调用适当的视图为用户提供反馈。\\n模型（Model）：模型是应用程序的主体部分。模型表示业务数据和业务逻辑。一个模型能为多个视图提供数据。\\n（1）JSP （2）Servlet （3）Service （4）JavaBean （5）DAO\\n【问题2】(6 分)\\n项目组架构师王工提出在图2-1所示架构设计中加入EJB构件，采用企业级JavaEE架构开发资源共享平台。请说明EJB构件中的Bean (构件)分为哪三种类型，每种类型Bean的职责是什么。\\n \\nEJB中的Bean分三种类型：Session Bean、Entity Beans 和 Message-Driven Bean。\\nSession Bean的职责是：维护一个短暂的会话\\nEntity Beans 的职责是：维护一行持久稳固的数据\\nMessage-Driven Bean的职责是：异步接受消息 \\n\\n【问题3】 (10分)\\n如果采用王工提出的企业 JavaEE架构，请说明下列(a)-(e) 所给出的业务功能构件中，有状态和无状态构件分别包括哪些。\\n（a）Identification Bean (身份认证构件)\\n（b）ResPublish Bean(资源发布构件)\\n（c）ResRetrieval Bean(资源检索构件)\\n（d）OnlineEdit Bean(在线编辑构件)\\n（e）Statistics Bean(统计分析构件)\\n\\n有状态：（a）、（d）\\n无状态：（b）、（c）、（e）\\n\\n试题三\\n阅读以下关于机器人操作系统架构的描述，回答问题1至问题3\\n【说明】\\n随着人工智能技术的发展，工业机器人已成为当前工业界的热点研究对象。某宇航设备公司为了扩大业务范围，决策层研究决定准备开展工业机器人研制新业务。公司将论证工作交给了软件架构师王工，王工经过分析和调研，从机器人市场现状、领域需求、组成及关键技术和风险分析等方面开展了综合论证。论证报告指出：首先，为了保障本公司机器人研制的持续性，应根据领域需求选择一种适应的设计架构；其次，为了规避风险，公司的研制工作不能从零开始，应该采用国际开源社区所提供机器人操作系统 (Robot Operating System ，ROS)作为机器人开发的基本平台。\\n在讨论会上，架构师李工提出不同意见，他认为公司针对宇航领域已开发了某款嵌 入式实时操作系统，且被多种宇航装备使用，可靠性较高。因此应该采用现有架构体系作为机器人的开发平台。会上王工说明了机器人操作系统与该款操作系统的差别，要沿用需要进行改造，技入较大。经过激烈讨论，公司领导同意了王工采用 ROS的意见。\\n \\n【问题1】(5分)\\n王工拟采用的ROS具有分布式进程框架，以点对点设计以及服务和节点管理器方式， 使得执行程序可以各自独立地设计，松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组，因而可以容易地分享和发布。请用400字以内文字说明ROS与嵌入式实时操作系统的共同点，以及在实时性和任务通信方式两个方面的差异。\\n \\nROS与嵌入式实时操作系统的共同点：\\n（1）系统微型化\\n（2）系统专用性强\\n（3）软硬件依赖性强\\n（4）系统资源受限\\nROS与嵌入式实时操作系统的差异：\\n实性性：ROS弱于嵌入式实时操作系统\\n通信方式：ROS的通信方式较为丰富，嵌入式实时操作系统通信方式单一。\\n【问题2】(10分)\\nROS为应用程序间通信提供了主题(Topic) 、服务 (Service)和动作 (Action) 三种消息通信方式，每种通信方式都有其特点。请将以下给出的三类通信的主要特点填入表3-1中(1)-(5) 的空白处，将答案写在答题纸上。\\n(a) 适合用于传输传感器信息〈数据流)\\n(b) 能够知道是否调用成功\\n(c) 一对多模式\\n(d) 有握手信号\\n(e) 服务执行完会有反馈\\n(f) 可以监控长时间执行的进程\\n(g) 较复杂\\n(h) 可能让系统过载(数据太多)\\n(i) 服务执行完之前，程序会等待\\n(j) 建立通信较慢\\n(k) 可能丢失数据\\n 【img:44d8dd06dfdffa7baad0be576dfea6fa4d278662ac396ae0c6fd158f6524140b】 \\n（1）（2）（c）（k） \\n（3）（4）（f）（i）\\n（5）（j） \\n【问题3】(10分)\\nROS 的架构定义了ROS系统由多个各自独立的节点(组件〉组成，并且各个节点之间可以通过发布/订阅(Publish/Subscribe )消息模型进行通信。图 3-1给出一个简单机器人结构实例，请根据以下文字描述，补充图3-1 中(1)~(5) 处空白，将答案写在答题纸上。\\n\\"机器人开始阶段，所有节点都要注册 (Registration) 到Master上，注册后，摄像头节点声明它要发布(Publish)一个叫做/image_data的消息。另外两个节点（图像处理处理节点和图像显示节点）声明它们需要订阅( Subscribe) 这个/image_data消息。因此， 一旦摄像头节点收到相机发送的数据(Data)，就立即将数据/image_data直接发送到另外两个节点。\\n 【img:d04dc47d94011e8c6647e279a56893f45e840e488274f9ab65fb5d0075eb818f】 \\n（1）Registration （2）Data （3）Publish （4）Subscribe （5）Subscribe\\n\\n试题四\\n阅读以下关于数据库设计的叙述，在答题纸上回答问题1至问题3。\\n【说明】\\n某制造企业为拓展网上销售业务，委托某软件企业开发一套电子商务网站。初期仅解决基本的网上销售、订单等功能需求。该软件企业很快决定基于.NET平台和SQL Server数据库进行开发，但在数据库访问方式上出现了争议。王工认为应该采用程序在 线访问的方式访问数据库；而李工认为本企业内部程序员缺乏数据库开发经验，而且应用筒单，应该采用ORM (对象关系映射)方式。最终经过综合考虑，该软件企业采用了李工的建议。\\n随着业务的发展，该电子商务网站逐渐发展成一个通用的电子商务平台，销售多家制造企业的产品，电子商务平台的功能也日益复杂。目前急需对该电子商务网站进行改造，以支持对多种异构数据库平台的数据访问，同时满足复杂的数据管理需求。该软件企业针对上述需求，对电子商务网站的架构进行了重新设计，新增加了数据访问层，同时采用工厂设计模式解决异构数据库访问的问题。新设计的系统架构如图 4-1 所示。\\n 【img:ede6baf2a516a682293c9fa0812413e5152be79849d98e1833c0562af776ce55】 \\n \\n【问题1】 (9分)\\n请用300字以内的文字分别说明数据库程序在线访问方式和ORM方式的优缺点，说明该软件企业采用ORM的原因。\\n数据库程序在线访问方式优点：\\n1、性能比直接SQL好\\n2、可以处理复杂查询语句\\n数据库程序在线访问方式缺点：\\n1、要求程序员懂SQL语句\\n2、修改与维护相对困难\\nORM优点：\\n1、使用ORM可以大大降低学习和开发成本。\\n2、程序员不用再写SQL来进行数据库操作。\\n3、减少程序的代码量。\\n4、降低由于SQL代码质量差而带来的影响。\\nORM缺点\\n1、不太容易处理复杂查询语句。\\n2、性能较直接用SQL差。\\n本题中的场景之所以选择ORM，主要考虑的是程序缺数据库开发经验，这样SQL语句质量有很大风险。同时学习成本很高。此外应用简单，不也担心ORM对性能的影响。\\n【问题2】(9分)\\n请用100字以内的文字说明新体系架构中增加数据访问层的原因。请根据图4-1所示，填写图中空白处(1) - (3)。\\n增加数据访问层的原因：\\n（1）由于涉及到多种异构数据库平台，数据访问复杂性增加，不宜与业务逻辑混合在一起\\n（2）数据管理变复杂之后，需要使用的代码量增加，分单独层次有利于让逻辑更清晰。\\n（3）业务逻辑应以相同的方式应对异构的数据库，此时需要单独的数据访问层屏蔽差异性。\\n（1）执行业务逻辑 （2）工厂层 （3）数据访问接口层\\n【问题3】(7分) \\n应用程序设计中，数据库访问需要良好的封装性和可维护性，因此经常使用工厂设计模式来实现对数据库访问的封装。请解释工厂设计模式，并说明其优点和应用场景:；请解释说明工厂模式在数据访问层中的应用。\\n工厂模式分抽象工厂与工厂方法，题目中的场景适合采用抽象工厂设计模式。\\n抽象工厂设计模式提供一个接口，可以创建一系列相关或相互依赖的对象，而无需指定它们具体的类。其优点是可以非常方便的创建一系列的对象，其使用场景也是创建系列对象的情况。在本题中，可以针对Oracle、MySQL、SQLServer分别建立抽象工厂，若指定当前工厂为Oracle工厂，则创建出来的数据库连接，数据集等一系列的对象都是符合Oracle操作要求的。这样便于数据库之间的切换。\\n\\n试题五\\n阅读以下关于Web系统架构设计的叙述，在答题纸上回答问题1至问题3.\\n【说明】\\n某电子商务企业因发展良好，客户量逐步增大，企业业务不断扩充，导致其原有的B2C商品交易平台己不能满足现有业务需求。因此，该企业委托某软件公司重新开发一套商品交易平台。该企业要求新平台应可适应客户从手机、平板设备、电脑等不同终端设备访问系统，同时满足电商定期开展\\"秒杀\\"、\\"限时促销\\"等活动的系统高并发访问量的需求。面对系统需求，软件公司召开项目组讨论会议，制定系统设计方案。讨论会议上，王工提出可以应用响应式Web设计满足客户从不同设备正确访问系统的需求。 同时，采用增加镜像站点、CDN 内容分发等方式解决高并发访问量带来的问题。李工在王工的提议上补充，仅仅依靠上述外网加速技术不能完全解决高用户并发访问问题，如果访问量持续增加，系统仍存在崩溃可能。李工提出应同时结合负载均衡、缓存服务器、Web应用服务器、分布式文件系统、分布式数据库等方法设计系统架构。经过项目组讨论，最终决定综合王王和李工的思路，完成新系统的架构设计。\\n \\n【问题1】(5分)\\n请用200字以内的文字描述什么是\\"响应式 Web 设计\\"，并列举2个响应式Web设计的实现方式。\\n响应式web设计是指我们设计与开发的页面可以根据用户的行为和不同的设备环境做出相应的响应来调整页面的布局，以提供用户可感知的、流畅的阅读和操作体验。\\n实现方式：\\n（1）流式布局\\n（2）弹性布局加媒体查询\\n【问题2】(16 分)\\n综合王工和李工的提议，项目组完成了新商品交易平台的系统架构设计方案。新系统架构图如图5-1所示。请从选项 (a) - (j) 中为架构图中(1) - (8) 处空白选择相应的内容，补充支持高并发的Web应用系统架构设计图。\\n 【img:36a9998114a9e60f99c54bc735f1c58767e68629017deed4ecbb06c0b045394e】 \\n(a) Web 应用层\\n(b) 界面层\\n(c) 负载均衡层\\n(d) CDN 内容分发\\n(e) 主数据库\\n(f) 缓存服务器集群\\n(g) 从数据库\\n(h) 写操作\\n(i) 读操作\\n(j) 文件服务器集群\\n（1）（d） \\n（2）（c） \\n（3）（f）\\n（4）（a） \\n（5）（6）（e）（h） \\n（7）（8）（g）（i） \\n\\n【问题3】(4 分)\\n根据李工的提议，新的B2C商品交易平台引入了主从复制机制。请针对B2C商品交易平台的特点，简要叙述引入该机制的好处。\\n1、提升性能\\n交易平台要求高并发，主从复制方式一主多从，不同的用户请求可以从不同的从数据库读取数据，提高并发度。\\n2、可扩展性更优\\n如果采用单台数据库服务器，则访问量持续增加时，数据库瓶颈暴露，且无法迅速解决问题。而主从结构可以快速增加从服务器数量，以满足需求。\\n3、提升可用性\\n一主多从，一台从服务器出现故障不影响整个系统正常工作。\\n4、相当于负载均衡\\n一主多从分担任务，相当于负载均衡\\n5、提升数据安全性\\n系统中的数据冗余存放多份，不会因为某台机器硬件故障而导致数据丢失。 \\n\\n试题一 论软件架构风格\\n软件体系结构风格是描述某一特定应用领域中系统组织方式的惯用模式。体系结构风格定义一个系统家族，即一个体系结构定义一个词汇表和一组约束。词汇表中包含一些构件和连接件类型，而这组约束指出系统是如何将这些构件和连接件组合起来的。体系结构风格反应了领域中众多系统所共有的结构和语义特性，并指导如何将各个模块和子系统有效地组织成一个完整的系统。\\n \\n请围绕\\"论软件架构风格''论题，依次从以下三个方面进行论述。\\n1.概要叙述你参与分析和设计的软件系统开发项目以及你所担任的主要工作。\\n2..软件系统开发中常用的软件架构风格有哪些?详细阐述每种风格的具体含义。\\n3.详细说明你所参与分析和设计的软件系统是采用什么软件架构风格的，并分析采用该架构风格设计的原因。\\n\\n一、结合自己所参与的软件项目，概要介绍该项目的背景及主要内容，并明确指出在其中所承担的主要任务和开展的主要工作。\\n二、常见的架构风格5大类，至少选2-3个类进行说明。（注意本部分内容虽然题目要求是详细论述，但实际上不是文章的重心，问题3才是结合项目的详细论述部分）\\nGarlan和Shaw将软件架构风格分为五大类，数据流风格、调用/返回风格、独立构件风格、虚拟机风格和仓库风格。其中：\\n（1）数据流风格包括批处理序列架构风格和管道/过滤器架构风格；\\n（2）调用/返回风格包括主程序/子程序架构风格、数据抽象和面向对象架构风格和层次结构架构风格；\\n（3）独立构件风格包括进程通信架构风格和事件驱动的架构风格；\\n（4）虚拟机风格包括解释器架构风格和基于规则的系统；\\n（5）仓库风格包括数据库架构风格和黑板架构风格。\\n其他的还有特定领域软件架构、状态转移等以及分布式处理等。其中分布式架构风格中有客户机/服务器风格、浏览器/服务器风格、CORBA、DCOM、EJB。\\n每一种具体的软件结构风格的模型如下：\\n1．数据流风格包括批处理序列和管道/过滤器架构风格。\\n（1）批处理序列架构风格。组件为一系列固定顺序的计算单元，组件间只通过数据传递交互。每个处理步骤是一个独立的程序，每一步必须在前一步结束后才能开始，数据必须是完整的，以整体的方式传递。\\n（2）管道/过滤器架构风格。每个构件都有一组输入和输出，构件读输入的数据流，经过内部处理，然后产生输出数据流，经过处理，产生输出数据流。这个过程通常通过对输入流的变换及增量计算来完成，包括通过计算和增加信息丰富数据，通过浓缩和删除精炼数据，通过改变记录方式转化数据，递增地转化数据等。在输入被完全消费之前，输出便产生了。这里构件被称为过滤器，连接件就是数据流传输的管道，将一个过滤器的输出传到另一过滤器的输入。\\n2．调用/返回风格包括主程序/子程序架构风格、数据抽象和面向对象架构风格以及层次结构架构风格\\n（1）主程序/子程序架构风格。单线程控制，把问题划分为若干处理步骤，构件即为主程序和子程序。子程序通常可合成为模块。过程调用作为交互机制，即充当连接件。调用关系具有层次性，其语义逻辑表现为子程序的正确性取决于它调用的子程序的正确性。\\n（2）数据抽象和面向对象架构风格。这种风格的构件是对象。对象是抽象数据类型的实例。在抽象数据类型中，数据的表示和它们的相应操作被封装起来。对象的行为体现在其接受和请求的动作。连接件即是对象间交互的方式，对象是通过函数和过程的调用来交互的。对象具有封装性，一个对象的改变不会影响其他对象。对象拥有状态和操作，也有责任维护状态。这种结构风格中包含有封装、交互、多态、集成、重用等特征。\\n（3）层次结构架构风格。层次系统组织成一个层次结构。构件在一些层实现了虚拟机。连接件通过决定层间如何交互的协议来定义，拓扑约束包括对相邻层间交互的约束。这个风格的特点是每层为上一层提供服务，使用下一层的服务，只能见到与自己邻接的层。大的问题分解为若干个渐进的小问题，逐步解决，隐藏了很多复杂度。修改一层，最多影响两层，而通常只能影响上层。上层必须知道下层的身份，不能调整层次之间的顺序。\\n3．独立构件风格包括进程通信架构风格和事件驱动的架构风格\\n（1）进程通信架构风格。构件是独立的过程，连接件是消息传递。这种风格的特点是构件通常是命名过程，消息传递的方式可以是点对点、异步和同步方式、以及远过程调用等\\n（2）事件驱动的架构风格。构件不直接调用一个过程，而是触发或广播一个或多个事件。系统中的其他构件中的过程在一个或多个事件中注册，当一个事件被触发，系统自动调用在这个事件中注册的所有过程。一个事件的触发就导致了另一个模块中的过程的调用。这种风格中的构件是非命名的过程，它们之间交互的连接件往往是以过程之间的隐式调用（Implicit Invocation）来实现的。基于事件的隐式调用风格的主要优点是为软件重用提供了强大的支持，为构件的维护和演化带来了方便，其缺点是构件放弃了对系统计算的控制。\\n4．虚拟机风格包括解释器架构风格和基于规则的系统\\n（1）解释器架构风格。一个解释器通常包括完成解释工作的解释引擎，一个包含将被解释的代码的存储区，一个记录解释引擎当前工作状态的数据结构，以及一个记录源代码被解释执行的进度的数据结构。具有解释器风格的软件中含有一个虚拟机，可以仿真硬件的执行过程和一些关键应用。其缺点是执行效率较低。\\n（2）基于规则的系统。基于规则的系统包括规则集、规则解释器、规则/数据选择器以及工作内存。\\n5．仓库风格包括数据库架构风格和黑板架构风格\\n（1）数据库架构风格。数据库架构是库风格最常见的形式。构件主要有两大类，一个是中央共享数据源，保存当前系统的数据状态，另一个是多个独立处理元素，处理元素对数据元素进行操作。\\n（2）黑板架构风格。黑板架构包括知识源、黑板、控制三部分。知识源包括若干独立计算的不同单元，提供解决问题的知识，知识源响应黑板上的变化，也只修改黑板。黑板是一个全局数据库，包含解域的全部状态，是知识源互相作用的唯一媒介。知识源响应是通过黑板状态的变化来控制。黑板通常应用在对于解决问题没有确定性算法的系统中，例如信号处理、问题规划、编译器优化等软件系统的设计中。\\n三、问题中明确要求回答选择架构的原因，其实是要求考生在组织论文时，说明作者选择架构的依据是什么，而各种架构应用在作者担任的项目中，有何优势与劣势。当这些内容分析清楚之后，合适的架构自然浮出水面来了。然后附带性的讲一讲架构的内容，架构具体内容与设计都已不是重心。最后谈一谈整体效果收尾。\\n\\n试题二 论软件系统建模方法及其应用\\n软件系统建模(Software System Modeling)是软件开发中的重要环节，通过构建软件系统模型可以帮助系统开发人员理解系统、抽取业务过程和管理系统的复杂性，也可以方便各类人员之间的交流。软件系统建模是在系统需求分析和系统实现之间架起的一座桥梁，系统开发人员按照软件系统模型开发出符合设计目标的软件系统，并基于该模型进行软件的维护和改进。\\n \\n请围绕\\"论软件系统建模方法及其应用\\"论题，依次从以下三个方面进行论述。\\n1.概要叙述你参与的软件系统开发项目以及你所担任的主要工作。\\n2.说明软件系统开发中常用的建模方法有哪几类?阐述每种方法的特点及其适用 范围。\\n3. 详细说明你所参与的软件系统开发项目中，采用了哪些软件系统建模方法，具体实施效果如何。\\n\\n一、应结合自己参与的信息系统项目，说明在其中所承担的工作。\\n二、需要较为详细地说明目前各种常见的信息系统建模方法的核心思想，并对每种方法所创建的模型进行简要描述。\\n（1）结构化建模方法。\\n结构化建模方法是以过程为中心的技术，可用于分析一个现有的系统以及定义新系统的业务需求。结构化建模方法所绘制的模型称为数据流图（DFD）。对于流程较为稳定的系统可考虑结构化建模方法。\\n（2）信息工程建模方法（或数据库建模方法）。\\n信息工程建模方法是一种以数据为中心，但过程敏感的技术，它强调在分析和研究过程需求之前，首先研究和分析数据需求。信息工程建模方法所创建的模型被称为实体联系图（ERD）。主要用于数据建模。\\n（3）面向对象建模方法。\\n面向对象建模方法将“数据”和“过程”集成到被称为“对象”的结构中，消除了数据和过程的人为分离现象。面向对象建模方法所创建的模型被称为对象模型。随着面向对象技术的不断发展和应用，形成了面向对象的建模标准，即UML（统一建模语言）。UML定义了几种不同类型的模型图，这些模型图以对象的形式共建一个信息系统或应用系统。目前比较常用的建模方法。\\n三、论文中需要结合项目实际工作，详细论述在项目中是如何使用所选定的信息系统建模方法创建系统的逻辑模型和物理模型，并详细说明实施效果。\\n\\n试题三 论无服务器架构及其应用\\n近年来，随着信息技术的迅猛发展和应用需求的快速更迭，传统的多层企业应用系统架构面临越来越多的挑战，已经难以适应这种变化。在这一背景下，无服务器架构(Serverless Architecture) 逐渐流行，它强调业务逻辑由事件触发，具有短暂的生命周期，运行于无状态的轻量级容器中，并且由第三方代为管理。采用无服务器架构，业务逻辑以功能即服务 （Function As a Service，FAAS) 的方式形成多个相互独立的功能组件，以标准接口的形式向外提供服务；同时，不同功能组件间的逻辑组织代码将存储在通用的基础设施管理平台中，业务代码仅在调用时才激活运行，当响应结束后占用的资源便会释放。\\n \\n请围绕\\"无服务器架构及其应用''论题，依次从以下三个方面进行论述。\\n1.概要叙述你参与分析和设计的软件系统开发项目以及你所担任的主要工作。\\n2.与传统的企业应用系统相比较，基于无服务器架构的应用系统具有哪些特点，请例举至少3个特点，并进行解释。\\n3. 结合你具体参与分析和设计的软件开发项目，描述该软件的架构，说明该架构是如何是如何采用无服务器架构模式的.，并说明在采用无服务器架构后软件开发过程中遇到的实际问题和解决方案。\\n一、结合自己所参与的软件项目，概要介绍该项目的背景及主要内容，并明确指出在其中所承担的主要任务和开展的主要工作。\\n二、问题2要求回答一些知识类型的问题，需要的知识内容如下：\\n首先值得说明的是无服务器架构并不是不再需要服务器，只是开发人员不再需要担心基础设施，因为一切都由云提供商负责。使用这种方法，开发人员只需部署适当的代码，其他一切由云提供商自动管理。\\n在传统的Web应用程序架构中，你必须管理基础架构，并确保其满足可扩展性和安全性需求。例如，客户端在一边，服务器在另一边。客户端发送一个“请求”，服务器回复“响应”。但是，如果无法满足应用程序需求，则很快就要扩展服务器端了。\\n无服务器模型提供了完全不同的方法。与传统架构不同，无服务架构在无状态计算容器中运行，这些容器是事件触发的，短暂的(只能持续一次调用)，并由第三方完全管理。就像一个“黑盒子”，这个服务你只需上传代码并实时自动处理。当一个请求进来时，就会运行你的Lambda功能的容器。\\n在成本方面，使用无服务器模型，通常仅支付服务请求和运行代码所需的计算时间。计费以100毫秒为单位进行计量，使其具有成本效益，并且易于自动从每天几个请求到每秒数千次都可以。\\n无服务器架构的优点包括：\\n（1）降低运营成本：无服务架构本质上是一个外包解决方案。基础设施不会消失。然而，与常规云服务相比，事实上，只需要根据流量规模和形式支付需要的计算量，这可能会大大节省运营成本，特别是对于具有不同变化的早期和动态应用负载要求。\\n（2）可扩展性强：可扩展性强在云服务领域并不新鲜，但无服务架构将其提升到一个全新的水平。无服务架构的缩放功能不仅可以降低计算成本，还可以减少运行管理，因为缩放是自动的。使用无服务器，无需明确添加和删除实例到服务器阵列，并让供应商为你扩展应用程序。由于云计算提供商根据每个请求执行扩展，所以甚至不需要考虑在内存不足之前可以处理多少并发请求的问题。\\n（3）分离问题：无服务器几乎迫使你实施关注模型的分离，通过该分离将应用程序分成不同的部分，以使每个部分都解决一个单独的问题。\\n（4）隔离进程：在无服务器环境中，每个Lambda函数都完全隔离。如果其中一个功能关闭，它不影响其他功能，它不会导致服务器崩溃。\\n无服务器架构的缺点包括：\\n（1）缺乏控制权：通过任何外包策略，你都可以将某些系统的控制权给第三方供应商。由于系统停机，意外的限制，成本的变化，功能的丧失，强制的API升级等，这种缺乏控制可能会显现出来。此外，如果需要专门的服务器进行专门的流程，那么必须自己运行这个专门的服务器。一个无服务器架构，在大多数情况下，提供商业化的基础设施，将以广义的方式运行你的流程。\\n（2）长时间运行流程的高成本：如果你的进程持续运行很长时间，则可能会需要运行自己的服务器。因为这不仅涉及到成本，还涉及到拥有的技能或者想要投入运行自己的服务器的专注;在评估这些解决方案时，请考虑所有这些方面。\\n（3）供应商锁定将基础架构管理完全外包给无服务器提供商，无疑将自己锁定到该供应商。每个供应商都有自己的标准和编程框架，不容易改变。在几乎每一种情况下，无论从供应商使用的无服务器功能，将由另一个供应商进行不同的实现。如果要切换供应商，几乎肯定需要更新操作工具(部署，监控等)，可能还需要更改代码。\\n三、结合项目经验详细论述无服务器架构的应用，并分析效果如何，哪些方面做得好，哪些方面做得不好。 \\n试题四 论软件质量保证及其应用\\n软件质量保证 (Software Quality Assurance. SQA) 是指为保证软件系统或软件产品充分满足用户要求的质量而进行的有计划、有组织的活动，这些活动贯穿于软件生产的整个生命周期。质量保证人员负责质量保证的计划、监督、记录、分析及报告工作，辅助软件开发人员得到高质量的最终产品。\\n \\n请围绕\\"软件质量保证及其应用\\"论题，依次从以下三个方面进行论述。\\n概要叙述你参与管理和开发的软件项目以及你在其中所担任的主要工作。\\n详细论述软件质量保证中常见的活动有哪些？阐述每个活动的主要内容。\\n结合你具体参与管理和开发的实际项目，说明是如何实施软件质量保证的各项活动，说明其实施过程及应用效果。\\n一、应结合自己参与的信息系统项目，说明在其中所承担的工作。\\n二、问题2涉及到一些知识性内容，需要的素材如下：\\n质量保证是指定期评估项目总体绩效，建立项目能达到相关质量标准的信心。质量保证对项目的最终结果负责，而且还要对整个项目过程承担质量责任；质量控制是指监测项目的总体结果，判断它们是否符合相关质量标准，并找出如何消除不合格绩效的方法。\\n软件质量保证（Software Quality Assurance，SQA）是指为保证软件系统或软件产品充分满足用户要求的质量而进行的有计划、有组织的活动，这些活动贯穿于软件生产的各个阶段即整个生命周期。SQA由各项任务构成，这些任务的参与者有两种人，分别是软件开发人员和质量保证人员。前者负责技术工作，后者负责质量保证的计划、监督、记录、分析及报告工作。软件开发人员通过采用可靠的技术、方法和措施，进行正式的技术评审，执行软件测试来保证软件产品的质量。质量保证人员则辅助软件开发人员得到高质量的最终产品。\\n美国卡耐基·梅隆大学软件工程研究所推荐了一组有关质量保证的计划、监督、记录、分析及报告的SQA活动，这些活动由一个独立的SQA小组执行。\\n（1）制订SQA计划。SQA计划在制订项目计划时制订，由相关部门审定。它规定了软件开发小组和质量保证小组需要执行的质量保证活动。有关该计划的详细内容，请阅读《系统分析师教程》20.7.2节。\\n（2）参与开发该软件项目的软件过程描述。软件开发小组为将要开展的工作选择软件过程，SQA小组则要评审过程说明，以保证该过程与企业政策、内部的软件标准、外界所制订的标准以及项目开发计划的其他部分相符。\\n（3）评审。评审各项软件工程活动，核实其是否符合已定义的软件过程。SQA小组识别、记录和跟踪所有偏离过程的偏差，核实其是否已经改正。\\n（4）审计。审计指定的软件工作产品，核实其是否符合已定义的软件过程中的相应部分。SQA小组对选出的产品进行评审，识别、记录和跟踪出现的偏差，核实其是否已经改正，定期向项目负责人报告工作结果。\\n（5）记录并处理偏差。确保软件工作及工作产品中的偏差已被记录在案，并根据预定规程进行处理。偏差可能出现在项目计划、过程描述、采用的标准或技术工作产品中。\\n（6）报告。记录所有不符合部分，并向上级管理部门报告。跟踪不符合的部分直到问题得到解决。\\n除了进行上述活动外，SQA小组还需要协调变更的控制与管理，并帮助收集和分析软件度量的信息。\\n三、结合具体参与的项目，从上面写到的几个方面来展开论述说明自己是如何进行质量保证工作的。最后总结效果，并指出不足，给出改进意见。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

